// Original synthesized arcade score. Audio starts only from a user gesture.
export class GameMusic {
 constructor(){this.enabled=false;this.playing=false;this.step=0;this.next=0;this.ward=50}
 async enable(value){this.enabled=value;try{if(value){this.ctx??=new(window.AudioContext||window.webkitAudioContext)();await this.ctx.resume();this.next=this.ctx.currentTime+.05}else if(this.ctx)await this.ctx.suspend()}catch{this.enabled=false}return this.enabled}
 note(freq,time,duration=.16,volume=.09,type='sine',end=freq){if(!this.ctx)return;const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(freq,time);o.frequency.exponentialRampToValueAtTime(Math.max(20,end),time+duration);g.gain.setValueAtTime(.0001,time);g.gain.exponentialRampToValueAtTime(Math.min(.8,volume*2.2),time+.008);g.gain.exponentialRampToValueAtTime(.0001,time+duration);o.connect(g);g.connect(this.ctx.destination);o.start(time);o.stop(time+duration+.02);o.onended=()=>{o.disconnect();g.disconnect()}}
 cue(kind){if(!this.enabled||!this.ctx||this.ctx.state!=='running')return;const t=this.ctx.currentTime;if(kind==='suck'){this.note(420,t,.3,.16,'triangle',75);this.note(170,t+.14,.16,.11,'sine',45);return}const seq=kind==='pop'?[523.25,659.25,783.99,1046.5]:kind==='win'?[523.25,659.25,783.99,1046.5,987.77,1046.5]:kind==='lose'?[392,329.63,261.63]:[392,523.25,659.25];seq.forEach((f,i)=>this.note(f,t+i*.095,kind==='win'?.32:.18,.16,'sine'))}
 tick(playing,ward){this.ward=ward;if(!this.enabled||!this.ctx||this.ctx.state!=='running')return;const now=this.ctx.currentTime;if(!playing){this.playing=false;this.next=now+.1;return}if(!this.playing){this.playing=true;this.next=now+.04;this.step=0}if(this.next<now)this.next=now+.04;const beat=ward===54?.145:.135,melody=ward===54?[76,0,79,0,83,81,79,0,76,0,74,76,79,0,74,0]:[72,0,76,79,0,76,74,0,72,0,67,0,74,76,79,0];while(this.next<now+.12){const i=this.step%32,n=melody[i%16],t=this.next,root=[48,45,53,55][Math.floor(i/8)];if(n)this.note(440*2**((n-69)/12),t,.12,.068,'sine');if(i%4===0){this.note(440*2**((root-69)/12),t,.22,.11,'triangle');this.note(95,t,.09,.095,'sine',35)}if(i%2===1)this.note(1800,t,.025,.022,'triangle',900);this.next+=beat;this.step++}}
}
